namespace L0 {
  static float L0_phase = 0.0f;

  void setup() {}

  void update(float dt, const InputFrame& input) {
    L0_phase = PFMath::fract(L0_phase + dt * 0.12f);
  }

  void draw() {
    const float invW = 1.0f / (float)FRAME_W;
    for (int x = 0; x < FRAME_W; x++) {
      float v = PFMath::fract((float)x * invW + L0_phase);
      for (int y = 0; y < FRAME_H; y++) {
        L0_setValue(x, y, v);
      }
    }
  }
}
